artifacts.body:
{
  "metadata": {
    "run_id": "cw-ms-remote-0a1b2c3d",
    "review_date": "2026-10-22",
    "last_updated": "2026-10-22T04:29:43.223526+00:00"
  },
  "company_name": "Cadence",
  "slug": "cadence",
  "stage": "seed",
  "sector": "B2B SaaS",
  "geography": "US",
  "sector_type": "saas"
}

{
  "items": [
    {
      "id": "structural_tam_gt_sam_gt_som",
      "category": "Structural Checks",
      "label": "TAM > SAM > SOM",
      "status": "pass",
      "notes": "Both builds respect the hierarchy. Top-down: TAM $800M > SAM $520M > SOM $5.2M. Bottom-up: TAM $700M > SAM $630M > SOM $6.3M. No inversion in either approach."
    },
    {
      "id": "structural_definitions_correct",
      "category": "Structural Checks",
      "label": "Definitions used correctly",
      "status": "pass",
      "notes": "TAM is defined as the full US FSM software market for the trades vertical (what the market would be if Cadence captured 100% of eligible businesses). SAM narrows to the SMB segment (1-50 technicians) that Cadence can actually serve. SOM is the share realistically capturable in the first three years. Definitions are applied consistently across both approaches."
    },
    {
      "id": "tam_matches_product_scope",
      "category": "TAM Scoping",
      "label": "TAM matches product scope",
      "status": "pass",
      "notes": "TAM is scoped to field service management software for HVAC, plumbing, and electrical trades businesses in the US \u2014 matching Cadence's product and target customer. The top-down build starts from the US FSM software market and applies a trades-specific filter (40%); the bottom-up build uses employer contractor establishment counts from Census for the same three NAICS codes. Neither inflates TAM with unrelated software categories or non-trade verticals."
    },
    {
      "id": "source_segments_match",
      "category": "TAM Scoping",
      "label": "Source segments match product segments",
      "status": "pass",
      "notes": "The primary US FSM market figure comes from IBISWorld (exact US segment match) and Global Market Insights (global, noted explicitly as broader). Contractor counts come from Census County Business Patterns 2023 data for NAICS 238220 (HVAC/plumbing) and NAICS 238210 (electrical), which match Cadence's target trades precisely. Grand View Research is used only for CAGR, with its broader scope noted. Mismatches between source scope and product scope are disclosed where they exist."
    },
    {
      "id": "som_share_defensible",
      "category": "SOM Realism",
      "label": "SOM share is defensible",
      "status": "pass",
      "notes": "SOM is set at 1% of SAM over three years, implying roughly 1,750 paying customers at $3,600 annual ARPU (~$6.3M ARR). For a seed-stage entrant in a fragmented SMB market with established incumbents (Jobber, Housecall Pro, ServiceTitan), 1% in three years is a conservative and defensible claim. It does not trigger the >5% red flag threshold for broad markets."
    },
    {
      "id": "som_backed_by_gtm",
      "category": "SOM Realism",
      "label": "SOM backed by go-to-market plan",
      "status": "fail",
      "notes": "No go-to-market plan, customer acquisition strategy, sales funnel metrics, or comparable-company benchmark was provided to support the SOM figure. The 1% capture rate is stated as an illustrative industry convention for early-stage SaaS, not derived from a specific GTM model. An investor will ask: how do you get to 1,750 customers \u2014 what channels, what sales motion, what conversion rates? This is the single most important gap to close before presenting the market sizing."
    },
    {
      "id": "som_consistent_with_projections",
      "category": "SOM Realism",
      "label": "SOM consistent with financial projections",
      "status": "fail",
      "notes": "No financial projections, hiring plan, or burn rate data were provided to cross-check against the SOM figure. The SOM implies approximately $6.3M ARR within three years. Without a financial model showing how many salespeople, what sales velocity, and what burn rate would be required to reach that, an investor cannot verify whether the SOM is operationally achievable."
    },
    {
      "id": "data_current",
      "category": "Data Quality",
      "label": "Data is current",
      "status": "pass",
      "notes": "All sources were accessed on the analysis date. Market figures come from IBISWorld 2025-2026, Grand View Research 2025, Global Market Insights 2025, and the ServiceTitan FY2025 10-K filed with the SEC. Contractor establishment counts are from Census County Business Patterns 2023, which is the most recently available Census annual release. Data is current for the sector."
    },
    {
      "id": "sources_reputable",
      "category": "Data Quality",
      "label": "Sources are reputable",
      "status": "pass",
      "notes": "Primary market size anchors are from IBISWorld and Grand View Research (analyst firms) and the ServiceTitan FY2025 SEC filing (regulatory filing). Census County Business Patterns data (government) underpins the contractor counts. Business press sources (StartBusinessByState, Vanta Insights, Pineido) are used only as secondary citations for Census data and competitor pricing \u2014 roles where primary data is either aggregated or publicly verifiable. No company blog or vendor marketing is used as a market-size baseline."
    },
    {
      "id": "figures_triangulated",
      "category": "Data Quality",
      "label": "Key figures triangulated",
      "status": "fail",
      "notes": "The US FSM software market total is cited from three analyst reports (IBISWorld, Global Market Insights, Precedence Research), which is solid triangulation. However, the SMB revenue share of the trades FSM market (65%) rests on a single Census establishment count combined with an agent-estimated revenue discount factor \u2014 no independent source confirms the 65% revenue split. The SOM capture rate (1%) has no external source at all. These two figures drive SAM and SOM respectively and are the weakest links in the chain."
    },
    {
      "id": "unsupported_figures_flagged",
      "category": "Data Quality",
      "label": "Unsupported figures flagged",
      "status": "pass",
      "notes": "Every assumption that lacks external sourcing is labeled as an agent estimate with confidence: low and notes that explicitly describe it as illustrative. The electrical non-employer business count, the non-employer adoption rate, the enterprise exclusion rate, the non-employer ARPU, and the 3-year capture rate are all flagged this way. The SOM figure validation entry is explicitly marked unsupported. Nothing unsupported is presented as a fact."
    },
    {
      "id": "validated_used_precisely",
      "category": "Data Quality",
